The experiment presented in Figure 2.4 illustrates the trade-off between spatial resolution and storage cost in memory. The code employs the subsampling technique via slicing to reduce the original pixel matrix according to a factor \(f\), resulting in memory savings — for example, a factor \(f=8\) reduces the data size by 64 times (\(8^2\)). For visual comparison purposes, the reduced images are restored to their original dimensions (\(512 \times 512\)) through nearest-neighbor interpolation (nearest). This process does not recover the lost information, but it makes evident the effect of aliasing and the block structure (pixelation) generated by the low data density of the sampled matrix.

%%writefile tmp/fig_02_subamostragem.cpp
#define MM_OUT "tmp/fig_02_subamostragem.png"
#include "morph.hpp"
#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;string&gt;
#include &lt;cmath&gt;

// #|
// #| label: fig-02-subamostragem
// #| fig-cap: "Efeito da subamostragem. Os títulos exibem as dimensões (W x H) e o tamanho da matriz em memória (KB)."
// #| echo: true
// #| output: true

struct SubsampleResult {
    mm::Image res;
    std::string label;
};

SubsampleResult subsample_simple(const mm::Image& image, int f) {
    // Subsampling via slicing
    mm::Image reduced = mm::subsample(image, f);

    // Memory calculation in KB
    double mem_kb = (reduced.h * reduced.w * reduced.channels) / 1024.0;
    std::string label = std::to_string(reduced.w) + "x" + std::to_string(reduced.h) + ", " + 
                        std::to_string(static_cast&lt;int&gt;(mem_kb)) + " KB\n(Factor " + std::to_string(f) + ")";

    // Restore size for visualization (original H, W)
    mm::Image res = mm::resize(reduced, image.w, image.h, "nearest");
    return {res, label};
}

int main() {
// [pdi:state-io] auto-generated — do not edit by hand
mm::Image img_gray = mm::_read_state("tmp/state/img_gray_22.png");
// [pdi:state-io:end]

    std::vector&lt;int&gt; factors = {1, 4, 8, 12};

    // Generate results and separate into lists for mm::show
    std::vector&lt;mm::Image&gt; imgs_list;
    std::vector&lt;std::string&gt; titles_list;
    for (int f : factors) {
        SubsampleResult r = subsample_simple(img_gray, f);
        imgs_list.push_back(r.res);
        titles_list.push_back(r.label);
    }

    mm::show(imgs_list, MM_OUT, titles_list, 4);

    return 0;
}

